borrowers = query_borrowers_by_city({"city": inputs["city"], "limit": 100})

edges = []
node_names = []
for borrower in borrowers:
    borrower_name = borrower.get("name")
    if borrower_name is None:
        continue
    node_names.append(borrower_name)
    guarantors = query_guarantors({"borrower_id": borrower.get("borrower_id")})
    for guarantor in guarantors or []:
        guarantor_name = guarantor.get("name")
        if guarantor_name is None:
            continue
        edges.append([borrower_name, guarantor_name])
        node_names.append(guarantor_name)

centrality_scores = {}
if edges:
    analysis = analyze_network({"edges": edges, "analysis": "centrality"})

    def extract_scores(obj):
        found = {}
        if isinstance(obj, dict):
            for key, value in obj.items():
                if isinstance(value, dict):
                    numeric = {k: v for k, v in value.items() if isinstance(v, (int, float)) and not isinstance(v, bool)}
                    if numeric and len(numeric) >= 1:
                        for nk, nv in numeric.items():
                            found[nk] = max(found.get(nk, float("-inf")), nv)
                    else:
                        found.update(extract_scores(value))
                elif isinstance(value, (list, tuple)):
                    for item in value:
                        found.update(extract_scores(item))
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                found.update(extract_scores(item))
        return found

    if isinstance(analysis, dict):
        direct = {}
        for node, score in analysis.items():
            if isinstance(score, (int, float)) and not isinstance(score, bool):
                direct[node] = score
        if direct:
            centrality_scores = direct
        else:
            centrality_scores = extract_scores(analysis)
    elif isinstance(analysis, list):
        centrality_scores = extract_scores(analysis)

    for node in node_names:
        if node not in centrality_scores:
            centrality_scores[node] = 0.0

ranked = sorted(centrality_scores.items(), key=lambda kv: (-kv[1] if isinstance(kv[1], (int, float)) else 0, str(kv[0])))
top_nodes = [{"name": name, "score": score} for name, score in ranked[:5]]

result = {
    "city": inputs["city"],
    "edges": edges,
    "top_nodes": top_nodes,
    "centrality": centrality_scores,
}

