monthly = {}
for rec in records:
    action_date = rec.get("action_date")
    if not action_date:
        continue
    month = action_date[:7]
    bucket = monthly.get(month)
    if bucket is None:
        bucket = {"month": month, "total_actions": 0, "success_count": 0}
        monthly[month] = bucket
    bucket["total_actions"] += 1
    if rec.get("outcome") in success_outcomes:
        bucket["success_count"] += 1

result = []
for month in sorted(monthly.keys()):
    bucket = monthly[month]
    total = bucket["total_actions"]
